    Call(Command),
}
#[derive(Debug, Deserialize, Serialize)]
struct Command {
    command: String,
    args: Option<Vec<String>>,
}
fn main() {
    for s in [
        r#"{"LogInfo":[1,2]}"#,
        r#"{"LogInfo":123}"#,
        r#"{"FocusByIndex":"foo"}"#,
        r#""foo""#,
        r#"{"Foo":"bar"}"#,
        r#"{"Call":{"command":"ls","args":"a"}}"#,
        r#"{"LogInfo":null}"#,
        r#"{"LogInfo":true}"#,
    ] {
        let r: Result<Message, _> = serde_json::from_str(s);
        println!("{:?} => {:?}", s, r);
        if let Err(e) = r {
            println!("  err {}", e);
            println!("  line {} col {}", e.line(), e.column());
        }
    }
    // Also test yaml to json conversion
    for y in [
        "LogInfo: [1,2]",
        "LogInfo: 123",
        "FocusByIndex: foo",
        "foo",
        "Foo: bar",
        "Call: {command: ls, args: a}",
    ] {
        let v: Result<serde_yaml::Value, _> = serde_yaml::from_str(y);
        println!("yaml {:?} => {:?}", y, v);
        if let Ok(val) = v {
            let j = serde_json::to_value(&val).unwrap();
            println!("  json value {:?}", j);
            println!("  json str {}", serde_json::to_string(&j).unwrap());
            let r: Result<Message, _> = serde_json::from_value(j);
            println!("  msg {:?}", r);
            if let Err(e) = r {
                println!("  err {}", e);
            }
            // Also try from_str via json string
            let js = serde_json::to_string(&serde_json::to_value(&val).unwrap()).unwrap();
            let r2: Result<Message, _> = serde_json::from_str(&js);
            println!("  from_str err {:?}", r2.err().map(|e| e.to_string()));
        } else if let Err(e) = v {
            println!("  yaml err {}", e);
        }
    }
}
