fn expand_placeholders(format: &str, args: &[String]) -> Result<String, String> {
    // Scan format for %, handling %%, %s, %q, invalid, incomplete, missing, too many.
    // Column counting: 1-indexed, counting characters? Or bytes? Need to handle unicode.
    // Original likely counts bytes? Or chars? Let's assume chars (Unicode scalar)? Or bytes?
    // For ASCII, same. For unicode template with multi-byte chars before %, need to test.
    // We'll count chars (Unicode scalar values) for column? Or bytes?
    // In Rust, format is &str (UTF-8), args are Strings.
    // We'll iterate over chars with byte index and char column.
    // For column in errors: `invalid placeholder '%d' at column X` and `placeholder missing value at column X`.
    // X is column of `%` (1-indexed). How to compute with unicode? Let's count chars (not bytes) for column? Common is chars.
    // We'll implement char counting.
    let mut result = String::new();
    let mut arg_idx = 0;
    let chars: Vec<char> = format.chars().collect();
    // Also need byte indices for slicing? We'll just iterate by char index.
    let mut col: usize = 1; // 1-indexed column for current char
    let mut idx = 0;
    while idx < chars.len() {
        let c = chars[idx];
        if c == '%' {
            if idx + 1 >= chars.len() {
                return Err("error: xplr -m: template ended with incomplete placeholder".to_string());
            }
            let next = chars[idx+1];
            if next == '%' {
                result.push('%');
                idx += 2;
                col += 2;
            } else if next == 's' {
                // Need value
                if arg_idx >= args.len() {
                    return Err(format!("error: xplr -m: placeholder missing value at column {}", col));
                }
                result.push_str(&args[arg_idx]);
                arg_idx += 1;
                idx += 2;
                col += 2;
            } else if next == 'q' {
                if arg_idx >= args.len() {
                    return Err(format!("error: xplr -m: placeholder missing value at column {}", col));
                }
                // JSON-quote the value (including quotes)
                let quoted = serde_json::to_string(&args[arg_idx]).unwrap();
                result.push_str(&quoted);
                arg_idx += 1;
                idx += 2;
                col += 2;
            } else {
                // Invalid placeholder
                return Err(format!("error: xplr -m: invalid placeholder '%{}' at column {}, use one of '%s' or '%q', or escape it using '%%'", next, col));
            }
        } else {
            result.push(c);
            idx += 1;
            col += 1;
        }
    }
    if arg_idx < args.len() {
        return Err("error: xplr -m: too many positional values, not enough positional placeholders".to_string());
    }
    Ok(result)
}

