fn main() {
    let args: Vec<String> = env::args().collect();
    // args[0] is program name
    let code = run(&args);
    std::process::exit(code);
}

fn run(args: &[String]) -> i32 {
    // Parse CLI sequentially
    let mut help_flag = false;
    let mut version_flag = false;
    let mut force_focus = false;
    let mut print_pwd_as_result = false;
    let mut read_only = false;
    let mut read0 = false;
    let mut write0 = false;
    let mut config: Option<String> = None;
    let mut extra_config: Vec<String> = Vec::new();
    let mut on_load: Vec<String> = Vec::new();
    let mut vroot: Option<String> = None;
    let mut msg_in: Option<(bool, String, String, Vec<String>)> = None; // (is_print, flag_name, format, args)
    let mut paths: Vec<String> = Vec::new(); // PATH + SELECTION
    let mut stdin_paths: Vec<String> = Vec::new();
    let mut after_double_dash = false;
    let mut stdin_consumed = false;
    let mut stdin_bytes: Vec<u8> = Vec::new(); // will read on demand? Actually need to read incrementally

    // For reading stdin on demand, we need to handle that stdin can only be read once.
    // We'll read all stdin upfront if needed? But need to handle order for delimiter?
    // Actually delimiter for first `-` depends on read0 before it, but stdin content is same.
    // We can read stdin bytes once (if any `-` present?), but need to handle that second `-` reads EOF (empty).
    // Simpler: read stdin bytes once at start if stdin is not tty? But then second `-` would incorrectly re-use same bytes.
    // Original behavior: first `-` consumes all stdin, second reads EOF (empty).
    // To replicate, we need to track whether stdin already consumed.
    // We'll lazily read: on first `-`, read all stdin into buffer, process, mark consumed.
    // On second `-`, process empty buffer.
    // However, if no `-`, don't read stdin at all (to avoid blocking).
    // Also need to handle that stdin reading happens immediately for validation order.

    let mut i = 1;
    while i < args.len() {
        // If msg_in already set (consumed rest), shouldn't happen because we break
        if after_double_dash {
            // All remaining are paths
            let p = &args[i];
            // Validate path (empty check, existence)
            if p.is_empty() {
                eprintln!("error: empty string passed");
                return 1;
            }
            if let Err(e) = validate_path(p) {
                eprintln!("{}", e);
                return 1;
            }
            paths.push(p.clone());
            i += 1;
            continue;
        }
        let a = &args[i];
        if a == "-" {
            // Read stdin with current read0
            let delim = if read0 { b'\0' } else { b'\n' };
            let input: Vec<u8>;
            if !stdin_consumed {
                // Read all stdin
                let mut buf = Vec::new();
                // Use read_to_end, but need to handle that stdin might be tty? In that case, read would block.
                // Original behavior when stdin is tty and `-` present? Probably reads from tty (blocking)? But in our test harness, stdin is pipe/file, not tty.
                // We'll just read.
                let stdin = io::stdin();
                let mut handle = stdin.lock();
                // Ignore errors? If read fails?
                let _ = handle.read_to_end(&mut buf);
                stdin_bytes = buf.clone();
                input = buf;
                stdin_consumed = true;
            } else {
                input = Vec::new();
            }
            // Split and validate
            let parts = split_stdin(&input, delim);
            // parts is Vec<Vec<u8>>? Or Vec<String>?
            for part in parts {
                if part.is_empty() {
                    eprintln!("error: empty string passed");
                    return 1;
                }
                // Convert part bytes to string (lossy? preserve bytes for error?)
                // For error message, need to show path with bytes as is (including nulls, newlines?).
                // We'll convert via String::from_utf8_lossy? But nulls are valid UTF-8, newlines valid.
                // For invalid UTF-8, lossy will replace, but original might show raw? Assume UTF-8.
                let s = String::from_utf8_lossy(&part).into_owned();
                // Validate existence (normalize, check)
                if let Err(e) = validate_path_bytes(&part) {
