            }
            let format = args[i+1].clone();
            let rest: Vec<String> = if i+2 < args.len() { args[i+2..].to_vec() } else { Vec::new() };
            msg_in = Some((is_print, flag_name, format, rest));
            // Break, no more parsing (rest consumed)
            break;
        } else if a == "-c" || a == "--config" {
            if i + 1 >= args.len() {
                eprintln!("error: usage: xplr {} PATH", a);
