                }
                if let Err(e) = validate_path(v) {
                    eprintln!("{}", e);
                    return 1;
                }
                extra_config.push(v.clone());
                j += 1;
            }
            i = j;
            continue;
        } else if a == "--on-load" {
            let mut j = i + 1;
            while j < args.len() {
                let v = &args[j];
                if v.starts_with('-') && !v.is_empty() {
                    break;
                }
                // Validate message immediately (on-load validation)
                if let Err(e) = validate_on_load_message(v) {
                    eprintln!("{}", e);
                    return 1;
                }
                on_load.push(v.clone());
                j += 1;
            }
            i = j;
            continue;
        } else if a.starts_with('-') && a.len() > 1 {
            // Unknown flag (including "-0m", "-Mm", etc., and "--badflag", "-c=/tmp", etc.)
            // Note: "-" alone already handled, "--" already handled.
            // So any other starting with '-' is invalid.
            eprintln!("error: invalid argument: {:?}, try `-- {:?}` or `--help`", a, a);
            return 1;
        } else {
            // Positional (PATH/SELECTION)
            // Empty check? For positional empty string, error `empty string passed` (as we saw for "" as PATH)
            if a.is_empty() {
                eprintln!("error: empty string passed");
                return 1;
            }
            if let Err(e) = validate_path(a) {
                eprintln!("{}", e);
                return 1;
            }
            paths.push(a.clone());
            i += 1;
            continue;
        }
    }

    // After parsing, check help/version/msg_in precedence
    if help_flag {
