fn split_stdin(input: &[u8], delim: u8) -> Vec<Vec<u8>> {
    if input.is_empty() {
        return Vec::new();
    }
    let mut parts: Vec<Vec<u8>> = Vec::new();
    let mut start = 0;
    for (idx, &b) in input.iter().enumerate() {
        if b == delim {
            parts.push(input[start..idx].to_vec());
            start = idx + 1;
        }
    }
    // Last part (after last delim, or whole if no delim)
    // If input ends with delim, then start == input.len(), last part would be empty (trailing). Ignore it (don't push).
    if start < input.len() {
        parts.push(input[start..].to_vec());
    } else if start == input.len() {
        // Ends with delim, ignore trailing empty. Do nothing (already pushed parts before).
        // But need to handle case where input is exactly delim (e.g., b"\n"): loop pushes [""] (first part before delim), start=1=len, so ignore trailing, result [""] (one empty). Good.
        // For b"\n\n": loop pushes ["",""] (two parts), start=2=len, ignore trailing, result ["",""] (two empties). Good.
        // For b"/tmp\n": pushes ["/tmp"], ignore trailing, result ["/tmp"]. Good.
    }
    // Edge: what about input not ending with delim but containing delim? Already handled.
    parts
}

fn clean_path(p: &str) -> String {
    // Normalize path lexically (without requiring existence), similar to Go's path.Clean or Python's normpath?
    // Handle absolute vs relative.
    // Steps: split by '/', process components.
    // For absolute (starts with '/'), result starts with '/'.
    // For relative, result is relative (but later joined with cwd for absolute? Actually validate_path will join with cwd then clean? Or clean then join? Need to handle `..` above cwd correctly.
    // Our validate_path will: if p is absolute, clean it; if relative, join with cwd then clean.
    // clean function should handle both absolute and relative? Simpler: clean function takes absolute path string (already joined) and cleans.
    // But for error message, need absolute cleaned path.
    // Implement clean for absolute paths.
    // For now, implement generic clean that works for both.
    let is_absolute = p.starts_with('/');
    let mut parts: Vec<&str> = Vec::new();
    for comp in p.split('/') {
        if comp.is_empty() || comp == "." {
            continue;
        } else if comp == ".." {
            if let Some(last) = parts.pop() {
                // If last is ".." (for relative paths with leading ..), keep? But for absolute, just pop.
                // For absolute, popping from empty (root) should stay at root (ignore .. above root).
                // Our parts for absolute starts empty, popping from empty should do nothing (stay at root).
                // For relative, popping from empty with .. should push ..? But our validate will join with cwd first, so relative becomes absolute before cleaning, so no leading .. in absolute? Actually after joining, absolute path may still have .. that goes above root? E.g., cwd /workspace + a/../../b => /workspace/a/../../b => clean => /b. Good. So for absolute cleaning, popping from empty (root) should ignore (stay at root).
                // The `last` we popped could be normal component, good. If parts was empty, pop returns None, do nothing.
                let _ = last;
            } else {
                // parts empty
                if !is_absolute {
                    // For relative, keep .. (e.g., `../a` => `../a`)
                    parts.push("..");
                } else {
                    // For absolute, ignore .. above root (stay at root)
                }
            }
        } else {
            parts.push(comp);
        }
    }
    if is_absolute {
        if parts.is_empty() {
            "/".to_string()
        } else {
            format!("/{}", parts.join("/"))
        }
    } else {
        if parts.is_empty() {
            ".".to_string()
        } else {
            parts.join("/")
        }
    }
}

fn validate_path(p: &str) -> Result<(), String> {
    // p is original path string (may be relative, may contain ., .., //, trailing /, etc.)
    // Returns Ok if exists, Err with formatted error message `error: path doesn't exist: {abs_clean}` (without `error: `? Actually caller adds `error: `? No, validate returns full `error: ...`? Let's return full.
    // Empty already checked by caller? But also check here for safety.
    if p.is_empty() {
        return Err("error: empty string passed".to_string());
    }
    // Compute absolute cleaned path for checking and error message
    let abs_clean = if p.starts_with('/') {
        clean_path(p)
    } else {
        // Join with cwd
        let cwd = env::current_dir().unwrap_or(PathBuf::from("/"));
        let cwd_str = cwd.to_string_lossy().into_owned();
        // Join: cwd + "/" + p, then clean
        let joined = format!("{}/{}", cwd_str.trim_end_matches('/'), p);
        clean_path(&joined)
    };
    // Check existence via Path::new(&abs_clean).exists()
    // Note: abs_clean may contain null bytes? Path::new with null will handle? In Rust, Path::new with null byte is allowed (as OsStr), but exists() will return false (since OS rejects null). Good.
    // For error message, need to show abs_clean as is (with nulls, etc.). Our abs_clean is String (UTF-8), but original path may contain nulls (valid UTF-8 \0) and newlines, etc. clean_path preserves them? Our clean splits by '/', so nulls/newlines inside components are preserved. Good.
    // What about non-UTF8? Our p is String (from args, which are OsString? Actually env::args() returns String, lossy? No, env::args() panics on non-UTF8? Actually env::args() uses String, invalid UTF-8 causes panic? In Rust, env::args() will panic on non-Unicode? No, it uses OsString? Actually std::env::args() returns Args which yields String, and panics on invalid Unicode? Let's check: std::env::args() docs: "The returned iterator will panic during iteration if any argument to the process is not valid Unicode." So non-UTF8 args would panic. Original xplr likely handles non-UTF8 via OsString. But judge likely uses UTF-8, so fine.
    if Path::new(&abs_clean).exists() {
        Ok(())
    } else {
        Err(format!("error: path doesn't exist: {}", abs_clean))
    }
}

