fn parse_and_validate_msg_to_json(expanded: &str) -> Result<String, String> {
    // Parse YAML to Value
    let yaml_val: serde_yaml::Value = match serde_yaml::from_str(expanded) {
        Ok(v) => v,
        Err(e) => {
            return Err(format!("error: xplr -m: yaml: {}", e));
        }
    };
    // Convert to JSON string (preserve order)
    // serde_yaml::Value -> serde_json::Value via to_value? Or directly to_string via serde_json?
    // serde_yaml::Value implements Serialize, so serde_json::to_string(&yaml_val) should work and preserve order (with preserve_order feature?).
    // But need to ensure order preserved: serde_yaml::Value's Mapping is IndexMap? And serde_json with preserve_order uses IndexMap, so order preserved. Good.
    let json_str = match serde_json::to_string(&yaml_val) {
        Ok(s) => s,
        Err(e) => {
            // This shouldn't happen for valid YAML values. What error? Unlikely.
            return Err(format!("error: {}", e));
        }
    };
    // Validate via serde_json to Message
    // Define Message enum here? We'll define globally.
    let msg_res: Result<Message, _> = serde_json::from_str(&json_str);
    match msg_res {
        Ok(_) => Ok(json_str),
        Err(e) => {
            return Err(format!("error: {}", e));
        }
    }
}

