        let line = if msg.ends_with('\n') { newlines + 1 } else { newlines + 2 };
        // Edge: empty string already handled (len 0), but empty also trims empty. Already returned.
        return Err(format!("error: invalid type: Option value, expected enum ExternalMsg at line {} column 1", line));
    }
    // Parse YAML to Value
    let yaml_val: Result<serde_yaml::Value, _> = serde_yaml::from_str(msg);
    let val = match yaml_val {
        Ok(v) => v,
        Err(e) => {
            return Err(format!("error: {}", e));
        }
    };
    // Validate Value against ExternalMsg
    validate_on_load_value(&val, msg)
}

fn validate_on_load_value(val: &serde_yaml::Value, orig_msg: &str) -> Result<(), String> {
    use serde_yaml::Value as Y;
    match val {
        Y::String(s) => {
            // Top-level string: check if unit, newtype, or unknown
            if is_unit_variant(s) {
                Ok(())
            } else if is_newtype_variant(s) {
                Err("error: invalid type: unit variant, expected newtype variant".to_string())
            } else {
                Err(format!("error: unknown variant `{}`, expected one of {}", s, variant_list_str()))
            }
        }
        Y::Mapping(map) => {
            if map.is_empty() {
                // Empty mapping {}: what error? Need to test original with "{}".
                // Let's assume `invalid type: map, expected enum ExternalMsg`? Or `Option value`? Need to test.
                // For now, return generic.
                // Test later: on-load "{}" ?
                return Err("error: invalid type: map, expected enum ExternalMsg".to_string());
            }
            // Get keys in order (IndexMap preserves order)
            let keys: Vec<&Y> = map.keys().collect();
            if keys.len() > 1 {
                // Multi-key mapping: check first key
                let first_key = keys[0];
                if let Y::String(k) = first_key {
                    if !is_valid_variant(k) {
                        return Err(format!("error: unknown variant `{}`, expected one of {}", k, variant_list_str()));
                    } else if is_unit_variant(k) {
                        return Err("error: invalid type: map, expected unit variant".to_string());
                    } else {
                        // First key newtype, multi-key => single key error
                        return Err("error: invalid value: map, expected map with a single key".to_string());
                    }
                } else {
                    // First key not string (e.g., int): what error? Likely `invalid type: ..., expected ...`? Need to test.
                    // For now, return generic.
                    return Err(format!("error: unknown variant `{:?}`, expected one of {}", first_key, variant_list_str()));
                }
            }
            // Single key mapping
            let (k, v) = map.iter().next().unwrap();
            // Key must be string? If not string, error?
            let key_str = match k {
                Y::String(s) => s.clone(),
                Y::Number(n) => {
                    // What error for int key? Need to test original with "{123: foo}".
                    // For now, return unknown? Or invalid type?
                    // Let's try to mimic: `invalid type: integer `123`, expected ...`? Or `unknown variant`?
                    // We'll return invalid type with no line/col? Need to test.
                    // For now, return unknown with debug?
                    // To be safe, return `error: invalid type: integer `...`, expected ...`? Hmm.
                    // Let's just return unknown variant with number string?
                    // Actually, YAML mapping keys can be non-string, but enum variant names are strings, so non-string key would give type error.
                    // We'll handle after testing.
                    // For now, return generic unknown.
                    let num_str = yaml_number_to_string(n);
                    // Try to match serde_yaml error for non-string key? In serde_yaml direct deserialization to enum, non-string key would give `invalid type: integer..., expected ...`?
                    // For top-level mapping with int key, on-load likely gives `invalid type: integer..., expected ...`? Let's assume no line/col? Need to test.
                    // For now, return:
                    return Err(format!("error: invalid type: integer `{}`, expected enum ExternalMsg", num_str));
                }
                _ => {
                    return Err(format!("error: unknown variant `{:?}`, expected one of {}", k, variant_list_str()));
                }
            };
            if !is_valid_variant(&key_str) {
                return Err(format!("error: unknown variant `{}`, expected one of {}", key_str, variant_list_str()));
            }
            if is_unit_variant(&key_str) {
                // Unit variant with mapping (any value) => error no line/col
                return Err("error: invalid type: map, expected unit variant".to_string());
            }
            // Newtype variant: validate value
            validate_on_load_newtype(&key_str, v, orig_msg)
        }
        Y::Sequence(_) => {
            Err("error: invalid type: sequence, expected enum ExternalMsg".to_string())
        }
        Y::Number(n) => {
            if n.as_i64().is_some() || n.as_u64().is_some() {
                // Integer (including negative? n.as_i64 for -5, as_u64 for 5)
                // Need to get string repr: for -5, "-5"; for 5, "5"
                let s = yaml_number_to_string(n);
                Err(format!("error: invalid type: integer `{}`, expected enum ExternalMsg", s))
            } else if n.as_f64().is_some() {
                let s = yaml_number_to_string(n);
                Err(format!("error: invalid type: floating point `{}`, expected enum ExternalMsg", s))
            } else {
                Err("error: invalid type: number, expected enum ExternalMsg".to_string())
            }
        }
        Y::Bool(b) => {
            Err(format!("error: invalid type: boolean `{}`, expected enum ExternalMsg", b))
        }
        Y::Null => {
            // Explicit null (e.g., "null", "~", etc.) vs empty/whitespace already handled before.
            // For explicit null, error `unit value` no line/col.
            Err("error: invalid type: unit value, expected enum ExternalMsg".to_string())
        }
        Y::Tagged(_) => {
            Err("error: invalid type: tagged, expected enum ExternalMsg".to_string())
        }
    }
}

