                            c_depth += 1;
                        } else if c == '}' {
                            if c_depth > 0 { c_depth -= 1; }
                        } else if c == ',' && b_depth == 0 && c_depth == 0 {
                            comma_count += 1;
                            if comma_count == idx {
                                // Next element starts after this comma + spaces
                                let mut q = byte_idx + 1;
                                while q < orig.len() && (bytes[q] == b' ' || bytes[q] == b'\t') {
                                    q += 1;
                                }
                                return orig[..q].chars().count() + 1;
                            }
                        }
                    }
                    prev_char = c;
                    byte_idx += 1;
                }
            }
        }
    }
    // Fallback
    yaml_col_top_value(orig)
}

fn yaml_type_str(v: &serde_yaml::Value) -> String {
    use serde_yaml::Value as Y;
    match v {
        Y::String(s) => format!("string {}", serde_json::to_string(s).unwrap()),
        Y::Number(n) => {
            if n.as_i64().is_some() || n.as_u64().is_some() {
                format!("integer `{}`", yaml_number_to_string(n))
            } else {
                format!("floating point `{}`", yaml_number_to_string(n))
            }
        }
        Y::Bool(b) => format!("boolean `{}`", b),
        Y::Null => "unit value".to_string(),
        Y::Sequence(_) => "sequence".to_string(),
        Y::Mapping(_) => "map".to_string(),
        Y::Tagged(_) => "tagged".to_string(),
    }
}

fn yaml_value_to_lenient_string(v: &serde_yaml::Value) -> Option<String> {
    use serde_yaml::Value as Y;
    match v {
        Y::String(s) => Some(s.clone()),
        Y::Number(n) => Some(yaml_number_to_string(n)),
        Y::Bool(b) => Some(b.to_string()),
        Y::Null => Some("null".to_string()),
        _ => None, // Sequence, Mapping, Tagged => None (invalid for String)
    }
}

fn validate_on_load_newtype(variant: &str, val: &serde_yaml::Value, orig: &str) -> Result<(), String> {
    use serde_yaml::Value as Y;
    // Check expected type for variant
    // String lenient variants
    if is_string_lenient_variant(variant) {
        match val {
            Y::String(_) | Y::Number(_) | Y::Bool(_) | Y::Null => Ok(()),
            Y::Sequence(_) | Y::Mapping(_) | Y::Tagged(_) => {
                let ty = yaml_type_str(val);
                let col = yaml_col_top_value(orig);
                Err(format!("error: {}: invalid type: {}, expected a string at line 1 column {}", variant, ty, col))
            }
        }
    } else if variant == "FocusNextByRelativeIndex" || variant == "FocusPreviousByRelativeIndex" || variant == "FocusByIndex" {
        // usize strict: only u64/i64 >=0? Actually usize: only non-negative int. Negative int fails with integer `-5`. Float fails, etc.
        match val {
            Y::Number(n) => {
                if let Some(u) = n.as_u64() {
                    // u64 always valid for usize? On 64-bit, usize is u64. Good. (What about huge u64 > usize::MAX on 32-bit? Ignore.)
                    let _ = u;
                    Ok(())
                } else if let Some(i) = n.as_i64() {
                    // i64: if negative, fail; if >=0, valid (since fits in usize? For large i64 > usize::MAX? Ignore.)
                    if i < 0 {
                        let col = yaml_col_top_value(orig);
                        Err(format!("error: {}: invalid type: integer `{}`, expected usize at line 1 column {}", variant, i, col))
                    } else {
                        Ok(())
                    }
                } else if n.as_f64().is_some() {
                    let s = yaml_number_to_string(n);
                    let col = yaml_col_top_value(orig);
                    Err(format!("error: {}: invalid type: floating point `{}`, expected usize at line 1 column {}", variant, s, col))
                } else {
                    Err(format!("error: {}: invalid type: number, expected usize", variant))
                }
            }
            Y::String(s) => {
                let col = yaml_col_top_value(orig);
                Err(format!("error: {}: invalid type: string {}, expected usize at line 1 column {}", variant, serde_json::to_string(s).unwrap(), col))
            }
            Y::Bool(b) => {
                let col = yaml_col_top_value(orig);
                Err(format!("error: {}: invalid type: boolean `{}`, expected usize at line 1 column {}", variant, b, col))
            }
            Y::Null => {
                let col = yaml_col_top_value(orig);
                Err(format!("error: {}: invalid type: unit value, expected usize at line 1 column {}", variant, col))
            }
            Y::Sequence(_) => {
                let col = yaml_col_top_value(orig);
                Err(format!("error: {}: invalid type: sequence, expected usize at line 1 column {}", variant, col))
            }
            Y::Mapping(_) => {
                let col = yaml_col_top_value(orig);
                Err(format!("error: {}: invalid type: map, expected usize at line 1 column {}", variant, col))
