fn validate_on_load_command(variant: &str, val: &serde_yaml::Value, orig: &str) -> Result<(), String> {
    use serde_yaml::Value as Y;
    match val {
        Y::Mapping(m) => {
            // Check for unknown fields, missing command, validate command (lenient String) and args (optional sequence of lenient String)
            // First, check unknown fields: allowed `command`, `args`
            for (k, _) in m.iter() {
                if let Y::String(ks) = k {
                    if ks != "command" && ks != "args" {
                        let col = yaml_col_field_name(orig, ks);
                        return Err(format!("error: {}: unknown field `{}`, expected `command` or `args` at line 1 column {}", variant, ks, col));
                    }
                } else {
                    // Non-string key? What error? For now, generic.
                    return Err(format!("error: {}: unknown field", variant));
                }
            }
            // Check missing command
            let has_command = m.iter().any(|(k,_)| matches!(k, Y::String(s) if s=="command"));
            if !has_command {
                let col = yaml_col_mapping_start(orig, variant);
                return Err(format!("error: {}: missing field `command` at line 1 column {}", variant, col));
            }
            // Validate command (lenient String): must be scalar, not sequence/mapping
            if let Some((_, v_cmd)) = m.iter().find(|(k,_)| matches!(k, Y::String(s) if s=="command")) {
                match v_cmd {
                    Y::String(_) | Y::Number(_) | Y::Bool(_) | Y::Null => {},
                    Y::Sequence(_) => {
                        let col = yaml_col_field_value(orig, "command");
                        return Err(format!("error: {}.command: invalid type: sequence, expected a string at line 1 column {}", variant, col));
                    }
                    Y::Mapping(_) => {
                        let col = yaml_col_field_value(orig, "command");
                        return Err(format!("error: {}.command: invalid type: map, expected a string at line 1 column {}", variant, col));
                    }
                    _ => {},
                }
            }
            // Validate args if present: must be sequence, each element lenient String (scalar, not sequence/mapping)
            if let Some((_, v_args)) = m.iter().find(|(k,_)| matches!(k, Y::String(s) if s=="args")) {
                match v_args {
                    Y::Sequence(seq) => {
                        for (idx, elem) in seq.iter().enumerate() {
                            match elem {
                                Y::String(_) | Y::Number(_) | Y::Bool(_) | Y::Null => {},
                                Y::Sequence(_) => {
                                    let col = yaml_col_array_elem(orig, "args", idx);
                                    return Err(format!("error: {}.args[{}]: invalid type: sequence, expected a string at line 1 column {}", variant, idx, col));
                                }
                                Y::Mapping(_) => {
                                    let col = yaml_col_array_elem(orig, "args", idx);
                                    return Err(format!("error: {}.args[{}]: invalid type: map, expected a string at line 1 column {}", variant, idx, col));
                                }
                                _ => {},
                            }
                        }
                    }
                    Y::String(s) => {
                        let col = yaml_col_field_value(orig, "args");
                        return Err(format!("error: {}.args: invalid type: string {}, expected a sequence at line 1 column {}", variant, serde_json::to_string(s).unwrap(), col));
                    }
                    Y::Number(n) => {
                        let ty = if n.as_i64().is_some() || n.as_u64().is_some() {
