// Helpers for YAML column computation (1-indexed, counting chars? Use bytes for ASCII)
fn yaml_col_top_value(orig: &str) -> usize {
    // Find first ':' then skip spaces, return col of next char (1-indexed)
    if let Some(colon) = orig.find(':') {
        let after = &orig[colon+1..];
        let mut offset = 0;
        for c in after.chars() {
            if c == ' ' || c == '\t' {
                offset += c.len_utf8();
            } else {
                break;
            }
        }
        // Column = byte index of value start +1? For ASCII, bytes==chars. For unicode before, need char count?
        // Original likely counts chars? Or bytes? Assume chars for now (count chars up to value).
        let byte_idx = colon + 1 + offset;
        // Count chars up to byte_idx
        orig[..byte_idx].chars().count() + 1
    } else {
        1
    }
}

fn yaml_col_field_value(orig: &str, field: &str) -> usize {
    // Find field name, then ':' after it, then value start
    if let Some(field_pos) = orig.find(field) {
        let after_field = &orig[field_pos + field.len()..];
        if let Some(colon_rel) = after_field.find(':') {
            let colon_abs = field_pos + field.len() + colon_rel;
            let after_colon = &orig[colon_abs+1..];
            let mut offset = 0;
            for c in after_colon.chars() {
                if c == ' ' || c == '\t' {
                    offset += c.len_utf8();
                } else {
                    break;
                }
            }
            let byte_idx = colon_abs + 1 + offset;
            return orig[..byte_idx].chars().count() + 1;
        }
    }
    // Fallback: top value
    yaml_col_top_value(orig)
}

fn yaml_col_field_name(orig: &str, field: &str) -> usize {
    if let Some(pos) = orig.find(field) {
        orig[..pos].chars().count() + 1
    } else {
        1
    }
}

fn yaml_col_mapping_start(orig: &str, variant: &str) -> usize {
    // Find '{' after variant:
    if let Some(var_pos) = orig.find(variant) {
        let after = &orig[var_pos + variant.len()..];
        if let Some(brace_rel) = after.find('{') {
            let abs = var_pos + variant.len() + brace_rel;
            return orig[..abs].chars().count() + 1;
        }
        // For block style (no '{'), find variant's ':' then next line? For now, return top value col?
        // E.g., "Call:\n  args: [a]" missing command: where is mapping start? Possibly line 2?
        // Original for block style missing field? Need to test. For now, fallback to top value.
    }
    yaml_col_top_value(orig)
}

