                        if let Y::String(ks) = k {
                            let col = yaml_col_top_value(orig); // Or col of key? Need to compute key col? For {a: 1}, key `a` starts after `{`? Original for RemoveNodeSorter with {a:1} gave col 25? Let's see: RemoveNodeSorter: {a: 1} with {a:1} gave `unknown variant `a`` at col 25? Earlier test for AddNodeFilterFromInput with {a:1} gave `unknown variant `a`` at col 25? Actually earlier test for AddNodeFilterFromInput with {a:1} gave `unknown variant `a``? We didn't test that exact, but for RemoveNodeSorter with {a:1} (via -M) gave unknown variant `a`? For on-load, need to test.
                            // For now, use top value col (which is start of `{`)? Or key col? Original for on-load with mapping for enum? Let's test later.
                            // Use field value col? Hmm.
                            return Err(format!("error: {}: unknown variant `{}`, expected one of {} at line 1 column {}", variant, ks, nodefilter_list_str(), col));
