                };
                let col = yaml_col_top_value(orig);
                Err(format!("error: {}: invalid type: {}, expected enum NodeSorter at line 1 column {}", variant, ty, col))
            }
            Y::Bool(b) => {
                let col = yaml_col_top_value(orig);
                Err(format!("error: {}: invalid type: boolean `{}`, expected enum NodeSorter at line 1 column {}", variant, b, col))
            }
            Y::Null => {
                let col = yaml_col_top_value(orig);
                Err(format!("error: {}: invalid type: unit value, expected enum NodeSorter at line 1 column {}", variant, col))
            }
            Y::Sequence(_) => {
                let col = yaml_col_top_value(orig);
                Err(format!("error: {}: invalid type: sequence, expected enum NodeSorter at line 1 column {}", variant, col))
            }
            Y::Mapping(_) => {
                if let Y::Mapping(m) = val {
                    if let Some((k, _)) = m.iter().next() {
                        if let Y::String(ks) = k {
                            let col = yaml_col_top_value(orig);
                            return Err(format!("error: {}: unknown variant `{}`, expected one of {} at line 1 column {}", variant, ks, nodesorter_list_str(), col));
                        }
                    }
                }
                let col = yaml_col_top_value(orig);
                Err(format!("error: {}: invalid type: map, expected enum NodeSorter at line 1 column {}", variant, col))
            }
            _ => Err(format!("error: {}: invalid type, expected enum NodeSorter", variant)),
        }
    } else {
        // Should not happen (all newtype covered)
        Ok(())
    }
}

fn is_string_lenient_variant(v: &str) -> bool {
    matches!(v,
        "FocusPath" | "FocusByFileName" | "ChangeDirectory" | "SetVroot" |
        "SetInputPrompt" | "BufferInput" | "SetInputBuffer" |
        "SwitchMode" | "SwitchModeKeepingInputBuffer" | "SwitchModeBuiltin" |
        "SwitchModeBuiltinKeepingInputBuffer" | "SwitchModeCustom" |
        "SwitchModeCustomKeepingInputBuffer" | "SwitchLayout" | "SwitchLayoutBuiltin" |
        "SwitchLayoutCustom" | "BashExec" | "BashExec0" | "BashExecSilently" |
        "BashExecSilently0" | "CallLua" | "CallLuaSilently" | "LuaEval" | "LuaEvalSilently" |
        "SelectPath" | "UnSelectPath" | "ToggleSelectionByPath" |
        "Search" | "SearchFuzzy" | "SearchFuzzyUnordered" | "SearchRegex" | "SearchRegexUnordered" |
        "StartFifo" | "ToggleFifo" | "LogInfo" | "LogSuccess" | "LogWarning" | "LogError" | "Debug"
    )
}

fn validate_on_load_inputop(val: &serde_yaml::Value, orig: &str) -> Result<(), String> {
    use serde_yaml::Value as Y;
    match val {
        Y::String(s) => {
            if s == "SetCursor" || s == "InsertCharacter" {
                // Newtype sub-variants without payload => error with prefix and col
                let col = yaml_col_top_value(orig);
                Err(format!("error: UpdateInputBuffer: invalid type: unit variant, expected newtype variant at line 1 column {}", col))
            } else if is_inputop_unit(s) {
                Ok(())
            } else if is_inputop(s) {
                // Should not happen (SetCursor/InsertCharacter already handled)
                Ok(())
            } else {
                let col = yaml_col_top_value(orig);
                Err(format!("error: UpdateInputBuffer: unknown variant `{}`, expected one of {} at line 1 column {}", s, inputop_list_str(), col))
            }
        }
        Y::Mapping(m) => {
            if m.len() != 1 {
                // Multi-key or empty? What error? For InputOperation with multi-key mapping? Likely `expected map with a single key`? Need to test.
                // For now, return generic.
                if m.is_empty() {
                    return Err("error: UpdateInputBuffer: invalid type: map, expected unit variant".to_string());
                } else {
                    // Check first key unknown?
                    if let Some((k, _)) = m.iter().next() {
                        if let Y::String(ks) = k {
                            if !is_inputop(ks) {
                                let col = yaml_col_top_value(orig);
                                return Err(format!("error: UpdateInputBuffer: unknown variant `{}`, expected one of {} at line 1 column {}", ks, inputop_list_str(), col));
                            }
                        }
                    }
                    return Err("error: UpdateInputBuffer: invalid value: map, expected map with a single key".to_string());
                }
            }
            let (k, v) = m.iter().next().unwrap();
            let key_str = match k {
                Y::String(s) => s.clone(),
                _ => {
                    let col = yaml_col_top_value(orig);
                    return Err(format!("error: UpdateInputBuffer: unknown variant `{:?}`, expected one of {} at line 1 column {}", k, inputop_list_str(), col));
                }
            };
            if !is_inputop(&key_str) {
                let col = yaml_col_top_value(orig);
