                let kc = yaml_col_field_name(orig, &key_str);
                // Actually for {Foo: bar}, key Foo starts after `{` + space. Our yaml_col_field_name finds first occurrence of Foo in orig (which is after `{`). Good.
                return Err(format!("error: UpdateInputBuffer: unknown variant `{}`, expected one of {} at line 1 column {}", key_str, inputop_list_str(), kc));
            }
            if key_str == "SetCursor" {
                // Expects usize
                match v {
                    Y::Number(n) => {
                        if n.as_u64().is_some() {
                            Ok(())
                        } else if let Some(i) = n.as_i64() {
                            if i < 0 {
                                let col = yaml_col_field_value(orig, "SetCursor");
                                Err(format!("error: UpdateInputBuffer.SetCursor: invalid type: integer `{}`, expected usize at line 1 column {}", i, col))
                            } else {
                                Ok(())
                            }
                        } else if n.as_f64().is_some() {
                            let s = yaml_number_to_string(n);
                            let col = yaml_col_field_value(orig, "SetCursor");
                            Err(format!("error: UpdateInputBuffer.SetCursor: invalid type: floating point `{}`, expected usize at line 1 column {}", s, col))
                        } else {
                            Err("error: UpdateInputBuffer.SetCursor: invalid type".to_string())
                        }
                    }
                    Y::String(s) => {
                        let col = yaml_col_field_value(orig, "SetCursor");
                        Err(format!("error: UpdateInputBuffer.SetCursor: invalid type: string {}, expected usize at line 1 column {}", serde_json::to_string(s).unwrap(), col))
                    }
                    Y::Bool(b) => {
                        let col = yaml_col_field_value(orig, "SetCursor");
                        Err(format!("error: UpdateInputBuffer.SetCursor: invalid type: boolean `{}`, expected usize at line 1 column {}", b, col))
                    }
                    Y::Null => {
                        let col = yaml_col_field_value(orig, "SetCursor");
                        Err(format!("error: UpdateInputBuffer.SetCursor: invalid type: unit value, expected usize at line 1 column {}", col))
                    }
                    Y::Sequence(_) => {
                        let col = yaml_col_field_value(orig, "SetCursor");
                        Err(format!("error: UpdateInputBuffer.SetCursor: invalid type: sequence, expected usize at line 1 column {}", col))
                    }
                    Y::Mapping(_) => {
                        let col = yaml_col_field_value(orig, "SetCursor");
                        Err(format!("error: UpdateInputBuffer.SetCursor: invalid type: map, expected usize at line 1 column {}", col))
                    }
                    _ => Err("error: UpdateInputBuffer.SetCursor: invalid type".to_string()),
                }
            } else if key_str == "InsertCharacter" {
                // Expects char (lenient: any scalar -> string -> single char)
                match v {
                    Y::String(s) => {
                        if s.chars().count() == 1 {
                            Ok(())
                        } else {
                            let col = yaml_col_field_value(orig, "InsertCharacter");
                            Err(format!("error: UpdateInputBuffer.InsertCharacter: invalid value: string {}, expected a character at line 1 column {}", serde_json::to_string(s).unwrap(), col))
                        }
                    }
                    Y::Number(n) => {
                        let s = yaml_number_to_string(n);
                        if s.chars().count() == 1 {
                            Ok(())
                        } else {
                            let col = yaml_col_field_value(orig, "InsertCharacter");
                            Err(format!("error: UpdateInputBuffer.InsertCharacter: invalid value: string {}, expected a character at line 1 column {}", serde_json::to_string(&s).unwrap(), col))
                        }
                    }
                    Y::Bool(b) => {
                        let s = b.to_string();
                        // "true"/"false" are multi-char, always fail
