                        Err(format!("error: UpdateInputBuffer.InsertCharacter: invalid type: map, expected a character at line 1 column {}", col))
                    }
                    _ => Err("error: UpdateInputBuffer.InsertCharacter: invalid type".to_string()),
                }
            } else {
                // Unit sub-variants with mapping (e.g., {GoToStart: null} or {GoToStart: 5})
                // For unit, value must be Null? Actually {GoToStart: null} should fail with `map, expected unit variant`? Earlier test: {GoToStart: null} gave `map, expected unit variant` with prefix and col (start of `{`? Actually col 20, start of `{` after UpdateInputBuffer:).
                // What about {GoToStart: 5} (unit with int)? Same error? Earlier test: {GoToStart: 5} gave same `map, expected unit variant`? Actually earlier test for {GoToStart: 5} gave same? Let's see: UpdateInputBuffer: {GoToStart: 5} gave `map, expected unit variant`? Earlier test for GoToStart with 5 gave `map, expected unit variant`? Actually earlier test for UpdateInputBuffer: {GoToStart: 5} (via on-load) gave `map, expected unit variant`? We tested {GoToStart: null} and {GoToStart: 5} both gave same? Yes, both gave `map, expected unit variant` at col 20.
                // So for unit sub-variants, any mapping (even with null) fails with same error (prefix + col of mapping start).
                let col = yaml_col_top_value(orig);
                Err(format!("error: UpdateInputBuffer: invalid type: map, expected unit variant at line 1 column {}", col))
            }
        }
        Y::Number(n) => {
            let ty = if n.as_i64().is_some() || n.as_u64().is_some() {
                format!("integer `{}`", yaml_number_to_string(n))
            } else {
                format!("floating point `{}`", yaml_number_to_string(n))
            };
            let col = yaml_col_top_value(orig);
            // What error for number for InputOperation? E.g., UpdateInputBuffer: 123 (int for enum). Likely `expected enum ...`? Or `expected ...`? Need to test original: UpdateInputBuffer: 123 ?
            // For now, return `invalid type: ..., expected ...`? Let's test later. Assume `expected ...`?
            // Actually for top-level enum with int, error is `expected enum ExternalMsg`. For nested enum with int, error is `expected enum NodeFilter` etc. For InputOperation with int, likely `expected enum ...`? What is InputOperation enum name? Possibly `InputOperation`? Let's assume.
            // Need to test original to get exact enum name. For now, use generic.
            // Let's return with prefix and col, but need enum name. We'll test and fix.
            Err(format!("error: UpdateInputBuffer: invalid type: {}, expected enum InputOperation at line 1 column {}", ty, col))
        }
        Y::Bool(b) => {
            let col = yaml_col_top_value(orig);
            Err(format!("error: UpdateInputBuffer: invalid type: boolean `{}`, expected enum InputOperation at line 1 column {}", b, col))
        }
        Y::Null => {
            let col = yaml_col_top_value(orig);
            Err(format!("error: UpdateInputBuffer: invalid type: unit value, expected enum InputOperation at line 1 column {}", col))
