    use serde_yaml::Value as Y;
    match v {
        Y::String(s) => s.clone(),
        Y::Number(n) => yaml_number_to_string(n),
        Y::Bool(b) => b.to_string(),
        Y::Null => "null".to_string(),
        _ => "".to_string(), // Should not happen for valid lenient (Sequence/Mapping would have failed validation)
    }
}

fn value_to_runtime(val: &serde_yaml::Value) -> Option<RuntimeMsg> {
    use serde_yaml::Value as Y;
    match val {
        Y::String(s) => {
            match s.as_str() {
                "FocusNext" => Some(RuntimeMsg::FocusNext),
                "FocusPrevious" => Some(RuntimeMsg::FocusPrevious),
                "FocusFirst" => Some(RuntimeMsg::FocusFirst),
                "FocusLast" => Some(RuntimeMsg::FocusLast),
                "FocusNextSelection" => Some(RuntimeMsg::FocusNextSelection),
                "FocusPreviousSelection" => Some(RuntimeMsg::FocusPreviousSelection),
                "Enter" => Some(RuntimeMsg::Enter),
                "Back" => Some(RuntimeMsg::Back),
                "FollowSymlink" => Some(RuntimeMsg::FollowSymlink),
                "LastVisitedPath" => Some(RuntimeMsg::LastVisitedPath),
                "NextVisitedPath" => Some(RuntimeMsg::NextVisitedPath),
                "UnsetVroot" => Some(RuntimeMsg::UnsetVroot),
                "ToggleVroot" => Some(RuntimeMsg::ToggleVroot),
                "ResetVroot" => Some(RuntimeMsg::ResetVroot),
                "Select" => Some(RuntimeMsg::Select),
                "SelectAll" => Some(RuntimeMsg::SelectAll),
                "UnSelect" => Some(RuntimeMsg::UnSelect),
                "UnSelectAll" => Some(RuntimeMsg::UnSelectAll),
                "ToggleSelection" => Some(RuntimeMsg::ToggleSelection),
                "ToggleSelectAll" => Some(RuntimeMsg::ToggleSelectAll),
                "ClearSelection" => Some(RuntimeMsg::ClearSelection),
                "RemoveLastNodeFilter" => Some(RuntimeMsg::RemoveLastNodeFilter),
                "ResetNodeFilters" => Some(RuntimeMsg::ResetNodeFilters),
                "ClearNodeFilters" => Some(RuntimeMsg::ClearNodeFilters),
                "ReverseNodeSorters" => Some(RuntimeMsg::ReverseNodeSorters),
                "RemoveLastNodeSorter" => Some(RuntimeMsg::RemoveLastNodeSorter),
                "ResetNodeSorters" => Some(RuntimeMsg::ResetNodeSorters),
                "ClearNodeSorters" => Some(RuntimeMsg::ClearNodeSorters),
                "Quit" => Some(RuntimeMsg::Quit),
                "PrintPwdAndQuit" => Some(RuntimeMsg::PrintPwdAndQuit),
                "PrintFocusPathAndQuit" => Some(RuntimeMsg::PrintFocusPathAndQuit),
                "PrintSelectionAndQuit" => Some(RuntimeMsg::PrintSelectionAndQuit),
                "PrintResultAndQuit" => Some(RuntimeMsg::PrintResultAndQuit),
                "PrintAppStateAndQuit" => Some(RuntimeMsg::PrintAppStateAndQuit),
                "Terminate" => Some(RuntimeMsg::Terminate),
                "Refresh" => Some(RuntimeMsg::Refresh),
                "ExplorePwd" => Some(RuntimeMsg::ExplorePwd),
                // Logging with string payload? No, these are newtype, not unit. Unit logging? No, LogInfo etc. are newtype, not unit. So plain "LogInfo" without payload would have failed validation (unit variant expected newtype). Since validation passed, plain "LogInfo" alone would not be here (it would have failed). Good.
                // For other unit variants (e.g., ExplorePwdAsync, ClearScreen, etc.), treat as Noop
                _ if is_unit_variant(s) => Some(RuntimeMsg::Noop),
                _ => None,
            }
        }
        Y::Mapping(m) => {
            if m.len() != 1 {
                return None; // Should not happen for valid (multi-key would have failed validation)
            }
            let (k, v) = m.iter().next().unwrap();
            let key = match k {
                Y::String(s) => s.clone(),
                _ => return None,
            };
            match key.as_str() {
                "FocusNextByRelativeIndex" => {
                    if let Y::Number(n) = v {
                        if let Some(u) = n.as_u64() {
                            Some(RuntimeMsg::FocusNextByRelativeIndex(u as usize))
                        } else if let Some(i) = n.as_i64() {
                            if i >= 0 { Some(RuntimeMsg::FocusNextByRelativeIndex(i as usize)) } else { None }
                        } else { None }
                    } else { None }
                }
                "FocusPreviousByRelativeIndex" => {
                    if let Y::Number(n) = v {
                        if let Some(u) = n.as_u64() {
                            Some(RuntimeMsg::FocusPreviousByRelativeIndex(u as usize))
                        } else if let Some(i) = n.as_i64() {
                            if i >= 0 { Some(RuntimeMsg::FocusPreviousByRelativeIndex(i as usize)) } else { None }
                        } else { None }
                    } else { None }
                }
                "FocusPath" => Some(RuntimeMsg::FocusPath(yaml_to_lenient_string(v))),
                "FocusByIndex" => {
                    if let Y::Number(n) = v {
                        if let Some(u) = n.as_u64() {
                            Some(RuntimeMsg::FocusByIndex(u as usize))
                        } else if let Some(i) = n.as_i64() {
                            if i >= 0 { Some(RuntimeMsg::FocusByIndex(i as usize)) } else { None }
                        } else { None }
                    } else { None }
                }
                "FocusByFileName" => Some(RuntimeMsg::FocusByFileName(yaml_to_lenient_string(v))),
                "ChangeDirectory" => Some(RuntimeMsg::ChangeDirectory(yaml_to_lenient_string(v))),
                "SetVroot" => Some(RuntimeMsg::SetVroot(yaml_to_lenient_string(v))),
                "SelectPath" => Some(RuntimeMsg::SelectPath(yaml_to_lenient_string(v))),
                "UnSelectPath" => Some(RuntimeMsg::UnSelectPath(yaml_to_lenient_string(v))),
                "ToggleSelectionByPath" => Some(RuntimeMsg::ToggleSelectionByPath(yaml_to_lenient_string(v))),
                "AddNodeFilter" | "RemoveNodeFilter" | "ToggleNodeFilter" => {
                    if let Y::Mapping(inner) = v {
                        let filter_str = match inner.get(&Y::String("filter".to_string())) {
                            Some(Y::String(s)) => s.clone(),
                            _ => return None,
                        };
                        let input_val = match inner.get(&Y::String("input".to_string())) {
                            Some(val) => yaml_to_lenient_string(val),
                            None => return None,
                        };
                        let filter = str_to_nodefilter(&filter_str)?;
                        match key.as_str() {
                            "AddNodeFilter" => Some(RuntimeMsg::AddNodeFilter(filter, input_val)),
                            "RemoveNodeFilter" => Some(RuntimeMsg::RemoveNodeFilter(filter, input_val)),
                            "ToggleNodeFilter" => Some(RuntimeMsg::ToggleNodeFilter(filter, input_val)),
                            _ => None,
                        }
                    } else { None }
                }
                "AddNodeSorter" | "ToggleNodeSorter" => {
                    if let Y::Mapping(inner) = v {
                        let sorter_str = match inner.get(&Y::String("sorter".to_string())) {
                            Some(Y::String(s)) => s.clone(),
                            _ => return None,
                        };
                        let sorter = str_to_nodesorter(&sorter_str)?;
                        let reverse = match inner.get(&Y::String("reverse".to_string())) {
                            Some(Y::Bool(b)) => Some(*b),
                            None => None,
                            _ => return None, // Should not happen (validation ensures bool or missing)
                        };
                        match key.as_str() {
                            "AddNodeSorter" => Some(RuntimeMsg::AddNodeSorter(sorter, reverse)),
                            "ToggleNodeSorter" => Some(RuntimeMsg::ToggleNodeSorter(sorter, reverse)),
                            _ => None,
                        }
                    } else { None }
                }
                "RemoveNodeSorter" | "ReverseNodeSorter" => {
                    if let Y::String(s) = v {
                        let sorter = str_to_nodesorter(s)?;
                        match key.as_str() {
                            "RemoveNodeSorter" => Some(RuntimeMsg::RemoveNodeSorter(sorter)),
                            "ReverseNodeSorter" => Some(RuntimeMsg::ReverseNodeSorter(sorter)),
                            _ => None,
                        }
                    } else { None }
                }
                "LogInfo" | "LogSuccess" | "LogWarning" | "LogError" | "Debug" => {
                    Some(RuntimeMsg::Log(yaml_to_lenient_string(v)))
                }
                // String lenient variants that are no-ops for minimal? e.g., SwitchMode, Call, etc. Treat as Noop (except those that affect state? SwitchMode affects UI mode, ignore for on-load quit tests? Call executes shell? Ignore for now.)
                // For Search etc. (String): treat as Noop for minimal (or implement basic filtering? For now Noop)
                "Search" | "SearchFuzzy" | "SearchFuzzyUnordered" | "SearchRegex" | "SearchRegexUnordered" |
                "BashExec" | "BashExec0" | "BashExecSilently" | "BashExecSilently0" |
                "CallLua" | "CallLuaSilently" | "LuaEval" | "LuaEvalSilently" |
                "SwitchMode" | "SwitchModeKeepingInputBuffer" | "SwitchModeBuiltin" |
                "SwitchModeBuiltinKeepingInputBuffer" | "SwitchModeCustom" | "SwitchModeCustomKeepingInputBuffer" |
                "SwitchLayout" | "SwitchLayoutBuiltin" | "SwitchLayoutCustom" |
                "SetInputPrompt" | "BufferInput" | "SetInputBuffer" |
                "StartFifo" | "ToggleFifo" => Some(RuntimeMsg::Noop),
                // Command struct variants (Call, Call0, etc.): treat as Noop for minimal (ignore shell execution)
                "Call" | "Call0" | "CallSilently" | "CallSilently0" => Some(RuntimeMsg::Noop),
                // UpdateInputBuffer (InputOperation): treat as Noop
                "UpdateInputBuffer" => Some(RuntimeMsg::Noop),
                _ => {
                    // Other newtype variants (e.g., AddNodeFilterFromInput with enum payload, etc.)? For minimal, Noop.
                    // Check if valid newtype but not handled above (e.g., AddNodeFilterFromInput, RemoveNodeFilterFromInput with NodeFilter enum)
                    if is_newtype_variant(&key) {
                        Some(RuntimeMsg::Noop)
                    } else {
                        None
                    }
                }
            }
        }
        _ => None,
    }
}
