// === TUI Full Implementation ===

fn abs_clean(path_str: &str) -> String {
    if path_str.starts_with('/') {
        clean_path(path_str)
    } else {
        let cwd = env::current_dir().unwrap_or(PathBuf::from("/"));
        let cwd_str = cwd.to_string_lossy().into_owned();
        let joined = format!("{}/{}", cwd_str.trim_end_matches('/'), path_str);
        clean_path(&joined)
    }
}

fn is_inside_vroot(pwd: &str, vroot: &str) -> bool {
    if pwd == vroot {
        return true;
    }
    if vroot == "/" {
        return pwd.starts_with('/');
    }
    let prefix = format!("{}/", vroot.trim_end_matches('/'));
    pwd.starts_with(&prefix)
}

#[derive(Debug, Clone)]
struct Node {
    path: String,
    relative: String,
    is_dir: bool,
    is_symlink: bool,
}

fn list_directory(pwd: &str, show_hidden: bool) -> Vec<Node> {
    let mut nodes = Vec::new();
    let read = match fs::read_dir(pwd) {
        Ok(r) => r,
        Err(_) => return nodes,
    };
    for entry in read {
        if let Ok(e) = entry {
            let file_name = e.file_name();
            let fname_str = file_name.to_string_lossy().into_owned();
            if !show_hidden && fname_str.starts_with('.') {
                continue;
            }
            let full_path = format!("{}/{}", pwd.trim_end_matches('/'), fname_str);
            let is_symlink = e.file_type().map(|t| t.is_symlink()).unwrap_or(false);
            let is_dir = fs::metadata(&full_path).map(|m| m.is_dir()).unwrap_or(false);
            nodes.push(Node {
                path: full_path,
                relative: fname_str,
                is_dir,
                is_symlink,
            });
        }
    }
    nodes.sort_by(|a, b| {
        match (a.is_dir, b.is_dir) {
            (true, false) => std::cmp::Ordering::Less,
            (false, true) => std::cmp::Ordering::Greater,
            _ => {
                natord_compare(&a.relative.to_lowercase(), &b.relative.to_lowercase())
                    .then_with(|| natord_compare(&a.relative, &b.relative))
            }
        }
    });
    nodes
}

fn natord_compare(a: &str, b: &str) -> std::cmp::Ordering {
    let ac: Vec<char> = a.chars().collect();
    let bc: Vec<char> = b.chars().collect();
    let mut i = 0;
    let mut j = 0;
    while i < ac.len() && j < bc.len() {
        let ca = ac[i];
        let cb = bc[j];
        if ca.is_ascii_digit() && cb.is_ascii_digit() {
            let mut ni = i;
            while ni < ac.len() && ac[ni].is_ascii_digit() { ni += 1; }
            let mut nj = j;
            while nj < bc.len() && bc[nj].is_ascii_digit() { nj += 1; }
            let num_a: String = ac[i..ni].iter().collect();
            let num_b: String = bc[j..nj].iter().collect();
            let ta = num_a.trim_start_matches('0');
            let tb = num_b.trim_start_matches('0');
            let ta = if ta.is_empty() { "0" } else { ta };
            let tb = if tb.is_empty() { "0" } else { tb };
            match ta.len().cmp(&tb.len()) {
                std::cmp::Ordering::Equal => {
                    match ta.cmp(&tb) {
                        std::cmp::Ordering::Equal => {},
                        other => return other,
                    }
                }
                other => return other,
            }
            i = ni;
            j = nj;
        } else {
            match ca.cmp(&cb) {
                std::cmp::Ordering::Equal => { i += 1; j += 1; }
                other => return other,
            }
