#[derive(Debug, Clone)]
struct Node { path: String, relative: String, is_dir: bool }
fn list_directory(pwd: &str, show_hidden: bool) -> Vec<Node> {
    let mut nodes = Vec::new();
    if let Ok(read) = fs::read_dir(pwd) {
        for entry in read.flatten() {
