    fn focus_path(&self) -> Option<String> { self.nodes.get(self.focus_index).map(|n| n.path.clone()) }
    fn result(&self) -> Vec<String> {
        if self.print_pwd_as_result { vec![self.pwd.clone()] }
        else if !self.selection.is_empty() { self.selection.clone() }
        else if let Some(f) = self.focus_path() { vec![f] } else { vec![] }
    }
}
fn push_history(state: &mut AppState, pwd: String) {
    // Truncate forward if not at end?
    if state.history_index + 1 < state.history.len() {
        state.history.truncate(state.history_index + 1);
    }
    state.history.push(pwd);
    state.history_index = state.history.len() - 1;
}
fn load_single_config(path_abs: &str) -> Result<(Option<bool>, Option<String>), String> {
    let content = match fs::read_to_string(path_abs) { Ok(c)=>c, Err(_)=> return Ok((None,None)), };
    let version_opt = extract_version(&content);
    let version_str = match version_opt {
        Some(v)=>v,
        None=> return Err(format!("'version' must be defined globally in {}", path_abs)),
    };
    let (core_ver, pre_opt) = if let Some(p)=version_str.find('-') {
        (&version_str[..p], Some(&version_str[p+1..]))
    } else { (version_str.as_str(), None) };
    if let Some(pre)=pre_opt {
        if pre.contains('.') && pre.chars().any(|c| c.is_ascii_digit()) {
            return Err(format!("incompatible script version in: {}. The script version is: {}, the required version is: 1.1.0. Visit https://xplr.dev/en/upgrade-guide", path_abs, version_str));
        }
    }
    let parts: Vec<&str> = core_ver.split('.').collect();
    if parts.len()!=3 {
        if parts.len()<3 { return Err("cannot parse integer from empty string".to_string()); }
        else { return Err(format!("incompatible script version in: {}. The script version is: {}, the required version is: 1.1.0. Visit https://xplr.dev/en/upgrade-guide", path_abs, version_str)); }
    }
    let mut nums=Vec::new();
    for p in &parts {
        if p.is_empty() { return Err("cannot parse integer from empty string".to_string()); }
        if !p.chars().all(|c| c.is_ascii_digit()) { return Err("invalid digit found in string".to_string()); }
        match p.parse::<u32>() { Ok(n)=>nums.push(n), Err(_)=> return Err("invalid digit found in string".to_string()), }
    }
    if nums[0]!=1 || nums[1]>1 || nums[2]!=0 {
        return Err(format!("incompatible script version in: {}. The script version is: {}, the required version is: 1.1.0. Visit https://xplr.dev/en/upgrade-guide", path_abs, version_str));
    }
    let mut sh=None; let mut pf=None;
    if content.contains("show_hidden") {
        if let Some(pos)=content.find("show_hidden") {
            let after=&content[pos+"show_hidden".len()..];
            if let Some(eq)=after.find('=') {
                let ae=after[eq+1..].trim_start();
                if ae.starts_with("true") { sh=Some(true); } else if ae.starts_with("false") { sh=Some(false); }
            }
        }
    }
    if content.contains("prompt") && content.contains("format") {
        if let Some(pp)=content.find("prompt") {
            let ap=&content[pp..];
            if let Some(fp)=ap.find("format") {
                let af=&ap[fp+"format".len()..];
                if let Some(eq)=af.find('=') {
                    let ae=af[eq+1..].trim_start();
                    if ae.starts_with('"') {
                        if let Some(e)=ae[1..].find('"') { pf=Some(ae[1..1+e].to_string()); }
                    } else if ae.starts_with('\'') {
                        if let Some(e)=ae[1..].find('\'') { pf=Some(ae[1..1+e].to_string()); }
                    }
                }
            }
        }
    }
    Ok((sh,pf))
}
fn extract_version(content: &str) -> Option<String> {
    let mut start=0;
    while let Some(pos_rel)=content[start..].find("version") {
        let pos_abs=start+pos_rel;
        let before_ok=if pos_abs==0 {true} else {let c=content[..pos_abs].chars().last().unwrap(); c.is_whitespace()||c==';'||c=='\n'||c=='\r'};
        let after_version=&content[pos_abs+"version".len()..];
        let after_ok=if after_version.is_empty() {false} else {let c=after_version.chars().next().unwrap(); c.is_whitespace()||c=='='};
        if before_ok&&after_ok {
            if let Some(eq_rel)=after_version.find('=') {
                let after_eq=after_version[eq_rel+1..].trim_start();
                if after_eq.starts_with('"') {
                    if let Some(e)=after_eq[1..].find('"') { return Some(after_eq[1..1+e].to_string()); } else { return None; }
                } else if after_eq.starts_with('\'') {
                    if let Some(e)=after_eq[1..].find('\'') { return Some(after_eq[1..1+e].to_string()); } else { return None; }
                } else { return None; }
            }
        }
        start=pos_abs+"version".len();
        if start>=content.len() {break;}
    }
    None
}
