                    if let Y::Mapping(inner)=v {
                        let f=match inner.get(&Y::String("filter".to_string())) { Some(Y::String(s))=>s.clone(), _=>return RMsg::Noop, };
                        let inp=match inner.get(&Y::String("input".to_string())) { Some(val)=>yaml_lenient(val), None=>return RMsg::Noop, };
                        if let Some(ff)=str_to_nodefilter(&f) { RMsg::AddFilter(ff,inp) } else {RMsg::Noop}
                    } else {RMsg::Noop}
                },
                "RemoveNodeFilter"=> {
                    if let Y::Mapping(inner)=v {
                        let f=match inner.get(&Y::String("filter".to_string())) { Some(Y::String(s))=>s.clone(), _=>return RMsg::Noop, };
                        let inp=match inner.get(&Y::String("input".to_string())) { Some(val)=>yaml_lenient(val), None=>return RMsg::Noop, };
                        if let Some(ff)=str_to_nodefilter(&f) { RMsg::RemoveFilter(ff,inp) } else {RMsg::Noop}
                    } else {RMsg::Noop}
                },
                "ToggleNodeFilter"=> {
                    if let Y::Mapping(inner)=v {
                        let f=match inner.get(&Y::String("filter".to_string())) { Some(Y::String(s))=>s.clone(), _=>return RMsg::Noop, };
                        let inp=match inner.get(&Y::String("input".to_string())) { Some(val)=>yaml_lenient(val), None=>return RMsg::Noop, };
                        if let Some(ff)=str_to_nodefilter(&f) { RMsg::ToggleFilter(ff,inp) } else {RMsg::Noop}
                    } else {RMsg::Noop}
                },
                "AddNodeSorter"|"ToggleNodeSorter"=> {
                    if let Y::Mapping(inner)=v {
                        let s=match inner.get(&Y::String("sorter".to_string())) { Some(Y::String(ss))=>ss.clone(), _=>return RMsg::Noop, };
                        let rev=match inner.get(&Y::String("reverse".to_string())) { Some(Y::Bool(b))=>Some(*b), None=>None, _=>return RMsg::Noop, };
                        if let Some(ss)=str_to_nodesorter(&s) {
