fn exec_msg(state: &mut AppState, msg: &RMsg, filters: &mut Vec<(NodeFilterRuntime,String)>, sorters: &mut Vec<(NodeSorterRuntime,bool)>) -> Option<i32> {
    match msg {
        RMsg::Noop=>None,
        RMsg::Refresh=>{
            state.nodes=list_directory_filtered(state, filters, sorters);
            if state.nodes.is_empty() {state.focus_index=0;} else if state.focus_index>=state.nodes.len() {state.focus_index=state.nodes.len()-1;}
            None
        },
        RMsg::Log(s)=>{state.logs.push(format!("INFO) {}",s)); None},
        RMsg::FocusNext=>{ if !state.nodes.is_empty() {state.focus_index=(state.focus_index+1)%state.nodes.len();} None},
        RMsg::FocusPrev=>{ if !state.nodes.is_empty() { if state.focus_index==0 {state.focus_index=state.nodes.len()-1;} else {state.focus_index-=1;}} None},
        RMsg::FocusFirst=>{ if !state.nodes.is_empty() {state.focus_index=0;} None},
        RMsg::FocusLast=>{ if !state.nodes.is_empty() {state.focus_index=state.nodes.len()-1;} None},
