fn list_directory_filtered(state: &AppState, filters: &[(NodeFilterRuntime,String)], sorters: &[(NodeSorterRuntime,bool)]) -> Vec<Node> {
    let mut nodes=list_directory(&state.pwd, state.show_hidden);
    if !filters.is_empty() {
        nodes.retain(|n| {
            for (f,i) in filters {
                if !apply_filter(f,i,n,&state.pwd) {return false;}
            }
            true
        });
    }
    if !sorters.is_empty() {
        nodes.sort_by(|a,b| {
            for (s,rev) in sorters {
                let ord=apply_sorter(s,a,b,&state.pwd);
                let ord=if *rev {ord.reverse()} else {ord};
                if ord!=std::cmp::Ordering::Equal {return ord;}
            }
            std::cmp::Ordering::Equal
        });
    }
    nodes
}
