}

fn yaml_lenient(v: &serde_yaml::Value) -> String {
    use serde_yaml::Value as Y;
    match v {
        Y::String(s)=>s.clone(),
        Y::Number(n)=>yaml_number_to_string(n),
        Y::Bool(b)=>b.to_string(),
        Y::Null=>"null".to_string(),
        _=>"".to_string(),
    }
}

fn parse_runtime(msg: &str) -> RMsg {
    let val: serde_yaml::Value = serde_yaml::from_str(msg).unwrap_or(serde_yaml::Value::Null);
    use serde_yaml::Value as Y;
    match val {
        Y::String(s) => match s.as_str() {
            "FocusNext"=>RMsg::FocusNext, "FocusPrevious"=>RMsg::FocusPrev,
            "FocusFirst"=>RMsg::FocusFirst, "FocusLast"=>RMsg::FocusLast,
            "Enter"=>RMsg::Enter, "Back"=>RMsg::Back, "FollowSymlink"=>RMsg::FollowSymlink,
            "UnsetVroot"=>RMsg::UnsetVroot, "ToggleVroot"=>RMsg::ToggleVroot, "ResetVroot"=>RMsg::ResetVroot,
            "Select"=>RMsg::Select, "SelectAll"=>RMsg::SelectAll,
            "UnSelect"=>RMsg::UnSelect, "UnSelectAll"=>RMsg::UnSelectAll,
            "ToggleSelection"=>RMsg::ToggleSel, "ToggleSelectAll"=>RMsg::ToggleSelAll, "ClearSelection"=>RMsg::ClearSel,
            "RemoveLastNodeFilter"=>RMsg::RemoveLastFilter, "ResetNodeFilters"=>RMsg::ResetFilters, "ClearNodeFilters"=>RMsg::ClearFilters,
            "ReverseNodeSorters"=>RMsg::ReverseSorters, "RemoveLastNodeSorter"=>RMsg::RemoveLastSorter, "ResetNodeSorters"=>RMsg::ResetSorters, "ClearNodeSorters"=>RMsg::ClearSorters,
            "Quit"=>RMsg::Quit, "PrintPwdAndQuit"=>RMsg::PrintPwd, "PrintFocusPathAndQuit"=>RMsg::PrintFocus,
            "PrintSelectionAndQuit"=>RMsg::PrintSel, "PrintResultAndQuit"=>RMsg::PrintResult, "PrintAppStateAndQuit"=>RMsg::PrintAppState,
            "Terminate"=>RMsg::Terminate, "Refresh"=>RMsg::Refresh, "ExplorePwd"=>RMsg::Refresh,
            _ if is_unit_variant(&s)=>RMsg::Noop,
            _=>RMsg::Noop,
        },
        Y::Mapping(m) => {
            if m.len()!=1 { return RMsg::Noop; }
            let (k,v)=m.iter().next().unwrap();
            let ks=match k { Y::String(s)=>s.clone(), _=>return RMsg::Noop, };
            match ks.as_str() {
                "FocusNextByRelativeIndex"=> if let Y::Number(n)=v { if let Some(u)=n.as_u64() { RMsg::FocusNextRel(u as usize) } else if let Some(i)=n.as_i64() { if i>=0 {RMsg::FocusNextRel(i as usize)} else {RMsg::Noop}} else {RMsg::Noop} } else {RMsg::Noop},
                "FocusPreviousByRelativeIndex"=> if let Y::Number(n)=v { if let Some(u)=n.as_u64() { RMsg::FocusPrevRel(u as usize) } else if let Some(i)=n.as_i64() { if i>=0 {RMsg::FocusPrevRel(i as usize)} else {RMsg::Noop}} else {RMsg::Noop} } else {RMsg::Noop},
                "FocusPath"=>RMsg::FocusPath(yaml_lenient(v)),
                "FocusByIndex"=> if let Y::Number(n)=v { if let Some(u)=n.as_u64() { RMsg::FocusByIndex(u as usize) } else if let Some(i)=n.as_i64() { if i>=0 {RMsg::FocusByIndex(i as usize)} else {RMsg::Noop}} else {RMsg::Noop} } else {RMsg::Noop},
                "FocusByFileName"=>RMsg::FocusByName(yaml_lenient(v)),
                "ChangeDirectory"=>RMsg::ChangeDir(yaml_lenient(v)),
                "SetVroot"=>RMsg::SetVroot(yaml_lenient(v)),
                "SelectPath"=>RMsg::SelectPath(yaml_lenient(v)),
                "UnSelectPath"=>RMsg::UnSelectPath(yaml_lenient(v)),
                "ToggleSelectionByPath"=>RMsg::ToggleSelPath(yaml_lenient(v)),
                "AddNodeFilter"=> {
                    if let Y::Mapping(inner)=v {
                        let f=match inner.get(&Y::String("filter".to_string())) { Some(Y::String(s))=>s.clone(), _=>return RMsg::Noop, };
                        let inp=match inner.get(&Y::String("input".to_string())) { Some(val)=>yaml_lenient(val), None=>return RMsg::Noop, };
                        if let Some(ff)=str_to_nodefilter(&f) { RMsg::AddFilter(ff,inp) } else {RMsg::Noop}
                    } else {RMsg::Noop}
                },
                "RemoveNodeFilter"=> {
                    if let Y::Mapping(inner)=v {
                        let f=match inner.get(&Y::String("filter".to_string())) { Some(Y::String(s))=>s.clone(), _=>return RMsg::Noop, };
                        let inp=match inner.get(&Y::String("input".to_string())) { Some(val)=>yaml_lenient(val), None=>return RMsg::Noop, };
                        if let Some(ff)=str_to_nodefilter(&f) { RMsg::RemoveFilter(ff,inp) } else {RMsg::Noop}
                    } else {RMsg::Noop}
                },
                "ToggleNodeFilter"=> {
                    if let Y::Mapping(inner)=v {
                        let f=match inner.get(&Y::String("filter".to_string())) { Some(Y::String(s))=>s.clone(), _=>return RMsg::Noop, };
                        let inp=match inner.get(&Y::String("input".to_string())) { Some(val)=>yaml_lenient(val), None=>return RMsg::Noop, };
                        if let Some(ff)=str_to_nodefilter(&f) { RMsg::ToggleFilter(ff,inp) } else {RMsg::Noop}
                    } else {RMsg::Noop}
                },
                "AddNodeSorter"|"ToggleNodeSorter"=> {
                    if let Y::Mapping(inner)=v {
                        let s=match inner.get(&Y::String("sorter".to_string())) { Some(Y::String(ss))=>ss.clone(), _=>return RMsg::Noop, };
                        let rev=match inner.get(&Y::String("reverse".to_string())) { Some(Y::Bool(b))=>Some(*b), None=>None, _=>return RMsg::Noop, };
                        if let Some(ss)=str_to_nodesorter(&s) {
                            if ks=="AddNodeSorter" { RMsg::AddSorter(ss,rev) } else { RMsg::ToggleSorter(ss,rev) }
                        } else {RMsg::Noop}
                    } else {RMsg::Noop}
                },
                "RemoveNodeSorter"=> if let Y::String(s)=v { if let Some(ss)=str_to_nodesorter(s) { RMsg::RemoveSorter(ss) } else {RMsg::Noop} } else {RMsg::Noop},
                "ReverseNodeSorter"=> if let Y::String(s)=v { if let Some(ss)=str_to_nodesorter(s) { RMsg::ReverseSorter(ss) } else {RMsg::Noop} } else {RMsg::Noop},
                "LogInfo"|"LogSuccess"|"LogWarning"|"LogError"|"Debug"=>RMsg::Log(yaml_lenient(v)),
                _ if is_newtype_variant(&ks)=>RMsg::Noop,
                _=>RMsg::Noop,
            }
        }
        _=>RMsg::Noop,
    }
}

