                },
                "RemoveNodeFilter"=> {
                    if let Y::Mapping(inner)=v {
                        let f=match inner.get(&Y::String("filter".to_string())) { Some(Y::String(s))=>s.clone(), _=>return RMsg::Noop, };
                        let inp=match inner.get(&Y::String("input".to_string())) { Some(val)=>yaml_lenient(val), None=>return RMsg::Noop, };
                        if let Some(ff)=str_to_nf(&f) { RMsg::RemoveFilter(ff,inp) } else {RMsg::Noop}
