fn parse_runtime(msg: &str) -> RMsg {
    let val: serde_yaml::Value = serde_yaml::from_str(msg).unwrap_or(serde_yaml::Value::Null);
    use serde_yaml::Value as Y;
    match val {
        Y::String(s) => match s.as_str() {
