            "FocusFirst"=>RMsg::FocusFirst, "FocusLast"=>RMsg::FocusLast,
            "Enter"=>RMsg::Enter, "Back"=>RMsg::Back, "FollowSymlink"=>RMsg::FollowSymlink,
            "UnsetVroot"=>RMsg::UnsetVroot, "ToggleVroot"=>RMsg::ToggleVroot, "ResetVroot"=>RMsg::ResetVroot,
            "Select"=>RMsg::Select, "SelectAll"=>RMsg::SelectAll,
            "UnSelect"=>RMsg::UnSelect, "UnSelectAll"=>RMsg::UnSelectAll,
            "ToggleSelection"=>RMsg::ToggleSel, "ToggleSelectAll"=>RMsg::ToggleSelAll, "ClearSelection"=>RMsg::ClearSel,
            "RemoveLastNodeFilter"=>RMsg::RemoveLastFilter, "ResetNodeFilters"=>RMsg::ResetFilters, "ClearNodeFilters"=>RMsg::ClearFilters,
            "ReverseNodeSorters"=>RMsg::ReverseSorters, "RemoveLastNodeSorter"=>RMsg::RemoveLastSorter, "ResetNodeSorters"=>RMsg::ResetSorters, "ClearNodeSorters"=>RMsg::ClearSorters,
            "Quit"=>RMsg::Quit, "PrintPwdAndQuit"=>RMsg::PrintPwd, "PrintFocusPathAndQuit"=>RMsg::PrintFocus,
            "PrintSelectionAndQuit"=>RMsg::PrintSel, "PrintResultAndQuit"=>RMsg::PrintResult, "PrintAppStateAndQuit"=>RMsg::PrintAppState,
            "Terminate"=>RMsg::Terminate, "Refresh"=>RMsg::Refresh, "ExplorePwd"=>RMsg::Refresh,
            _ if is_unit_variant(&s)=>RMsg::Noop,
            _=>RMsg::Noop,
        },
        Y::Mapping(m) => {
            if m.len()!=1 { return RMsg::Noop; }
            let (k,v)=m.iter().next().unwrap();
            let ks=match k { Y::String(s)=>s.clone(), _=>return RMsg::Noop, };
            match ks.as_str() {
                "FocusNextByRelativeIndex"=> if let Y::Number(n)=v { if let Some(u)=n.as_u64() { RMsg::FocusNextRel(u as usize) } else if let Some(i)=n.as_i64() { if i>=0 {RMsg::FocusNextRel(i as usize)} else {RMsg::Noop}} else {RMsg::Noop} } else {RMsg::Noop},
                "FocusPreviousByRelativeIndex"=> if let Y::Number(n)=v { if let Some(u)=n.as_u64() { RMsg::FocusPrevRel(u as usize) } else if let Some(i)=n.as_i64() { if i>=0 {RMsg::FocusPrevRel(i as usize)} else {RMsg::Noop}} else {RMsg::Noop} } else {RMsg::Noop},
                "FocusPath"=>RMsg::FocusPath(yaml_lenient(v)),
                "FocusByIndex"=> if let Y::Number(n)=v { if let Some(u)=n.as_u64() { RMsg::FocusByIndex(u as usize) } else if let Some(i)=n.as_i64() { if i>=0 {RMsg::FocusByIndex(i as usize)} else {RMsg::Noop}} else {RMsg::Noop} } else {RMsg::Noop},
