fn list_filtered(state: &AppState, filters: &[(NodeFilter,String)], sorters: &[(NodeSorter,bool)]) -> Vec<Node> {
    let mut nodes=list_directory(&state.pwd, state.show_hidden);
    if !filters.is_empty() {
        nodes.retain(|n| { for (f,i) in filters { if !apply_filter_nf(f,i,n) {return false;}} true });
    }
    if !sorters.is_empty() {
        nodes.sort_by(|a,b| {
            for (s,rev) in sorters {
                let o=apply_sorter_ns(s,a,b);
                let o=if *rev {o.reverse()} else {o};
                if o!=std::cmp::Ordering::Equal {return o;}
            }
            std::cmp::Ordering::Equal
        });
    }
    nodes
}
