        ByIsFile|ByCanonicalIsFile=>{let af=!a.is_dir; let bf=!b.is_dir; af.cmp(&bf)},
        ByIsSymlink=>{
            let al=fs::symlink_metadata(&a.path).map(|m| m.file_type().is_symlink()).unwrap_or(false);
            let bl=fs::symlink_metadata(&b.path).map(|m| m.file_type().is_symlink()).unwrap_or(false);
            al.cmp(&bl)
        },
        ByIsBroken=>{
            let al=fs::symlink_metadata(&a.path).map(|m| m.file_type().is_symlink()).unwrap_or(false) && fs::metadata(&a.path).is_err();
            let bl=fs::symlink_metadata(&b.path).map(|m| m.file_type().is_symlink()).unwrap_or(false) && fs::metadata(&b.path).is_err();
            al.cmp(&bl)
        },
        ByIsReadonly|ByCanonicalIsReadonly=>{
            let ar=fs::metadata(&a.path).map(|m| m.permissions().readonly()).unwrap_or(false);
            let br=fs::metadata(&b.path).map(|m| m.permissions().readonly()).unwrap_or(false);
            ar.cmp(&br)
        },
        BySymlinkIsReadonly=>{
            let ar=fs::symlink_metadata(&a.path).map(|m| m.permissions().readonly()).unwrap_or(false);
            let br=fs::symlink_metadata(&b.path).map(|m| m.permissions().readonly()).unwrap_or(false);
            ar.cmp(&br)
        },
        BySize|ByCanonicalSize=>{
            let al=fs::metadata(&a.path).map(|m| m.len()).unwrap_or(0);
            let bl=fs::metadata(&b.path).map(|m| m.len()).unwrap_or(0);
            al.cmp(&bl)
        },
        BySymlinkSize=>{
            let al=fs::symlink_metadata(&a.path).map(|m| m.len()).unwrap_or(0);
            let bl=fs::symlink_metadata(&b.path).map(|m| m.len()).unwrap_or(0);
            al.cmp(&bl)
        },
        ByLastModified|ByCanonicalLastModified=>{
            let am=fs::metadata(&a.path).and_then(|m| m.modified()).ok();
            let bm=fs::metadata(&b.path).and_then(|m| m.modified()).ok();
            am.cmp(&bm)
        },
        BySymlinkLastModified=>{
            let am=fs::symlink_metadata(&a.path).and_then(|m| m.modified()).ok();
            let bm=fs::symlink_metadata(&b.path).and_then(|m| m.modified()).ok();
            am.cmp(&bm)
        },
        ByCreated|ByCanonicalCreated=>{
            let ac=fs::metadata(&a.path).and_then(|m| m.created()).ok();
            let bc=fs::metadata(&b.path).and_then(|m| m.created()).ok();
            ac.cmp(&bc)
        },
        BySymlinkCreated=>{
            let ac=fs::symlink_metadata(&a.path).and_then(|m| m.created()).ok();
            let bc=fs::symlink_metadata(&b.path).and_then(|m| m.created()).ok();
            ac.cmp(&bc)
        },
        ByCanonicalAbsolutePath|BySymlinkAbsolutePath=>natord_compare(&a.path,&b.path),
        ByICanonicalAbsolutePath|ByISymlinkAbsolutePath=>natord_compare(&a.path.to_lowercase(),&b.path.to_lowercase()),
        ByCanonicalExtension|BySymlinkExtension=>{
            let ea=Path::new(&a.relative).extension().and_then(|x| x.to_str()).unwrap_or("");
