            natord_compare(ea,eb)
        },
        ByMimeEssence|ByCanonicalMimeEssence|BySymlinkMimeEssence=>{
            let ea=Path::new(&a.relative).extension().and_then(|x| x.to_str()).unwrap_or("");
            let eb=Path::new(&b.relative).extension().and_then(|x| x.to_str()).unwrap_or("");
            natord_compare(ea,eb)
        },
        BySymlinkIsDir=>a.is_dir.cmp(&b.is_dir),
        BySymlinkIsFile=>{let af=!a.is_dir; let bf=!b.is_dir; af.cmp(&bf)},
    }
}
fn list_filtered(state: &AppState, filters: &[(NodeFilter,String)], sorters: &[(NodeSorter,bool)]) -> Vec<Node> {
    let mut nodes=list_directory(&state.pwd, state.show_hidden);
    if !filters.is_empty() {
        nodes.retain(|n| { for (f,i) in filters { if !apply_filter_nf(f,i,n) {return false;}} true });
    }
    if !sorters.is_empty() {
        nodes.sort_by(|a,b| {
            for (s,rev) in sorters {
                let o=apply_sorter_ns(s,a,b);
                let o=if *rev {o.reverse()} else {o};
                if o!=std::cmp::Ordering::Equal {return o;}
            }
            std::cmp::Ordering::Equal
        });
    }
    nodes
}
