fn run_tui(
    config_opt: Option<String>,
    extra_config: Vec<String>,
    on_load: Vec<String>,
    vroot_opt: Option<String>,
    paths: Vec<String>,
    stdin_paths: Vec<String>,
    force_focus: bool,
    print_pwd_as_result: bool,
    _read_only: bool,
    write0: bool,
) -> i32 {
    let (init_path_str, init_sel_strs): (String, Vec<String>) = if !stdin_paths.is_empty() {
        let p = stdin_paths[0].clone();
        let mut sel = Vec::new();
        if stdin_paths.len()>1 { sel.extend_from_slice(&stdin_paths[1..]); }
        sel.extend_from_slice(&paths);
        (p, sel)
    } else {
        if paths.is_empty() { (".".to_string(), Vec::new()) }
        else { (paths[0].clone(), if paths.len()>1 {paths[1..].to_vec()} else {Vec::new()}) }
    };
    let init_path_abs = abs_clean(&init_path_str);
    let mut init_sel_abs: Vec<String> = Vec::new();
    for s in &init_sel_strs { init_sel_abs.push(abs_clean(s)); }
    let init_is_dir = fs::metadata(&init_path_abs).map(|m| m.is_dir()).unwrap_or(false);
    let initial_pwd: String;
    let initial_focus: Option<String>;
    if init_is_dir && !force_focus {
        initial_pwd = init_path_abs.clone();
        initial_focus = None;
    } else {
        let parent = Path::new(&init_path_abs).parent().map(|p| p.to_string_lossy().into_owned()).unwrap_or("/".to_string());
        let pc = if parent.is_empty() {"/".to_string()} else {clean_path(&parent)};
        initial_pwd = pc;
        initial_focus = Some(init_path_abs.clone());
    }
    let vroot_abs_opt: Option<String> = vroot_opt.as_ref().map(|v| abs_clean(v));
    if let Some(ref vr) = vroot_abs_opt {
        if !is_inside_vroot(&initial_pwd, vr) {
            eprintln!("error: {:?} is outside of virtual root {:?}", initial_pwd, vr);
            return 1;
        }
    }
    match fs::OpenOptions::new().read(true).write(true).open("/dev/tty") {
        Ok(_)=>{},
        Err(e)=>{ eprintln!("error: {}",e); return 1; }
    }
    // Config
    let mut show_hidden=false;
    let mut prompt_format="❯ ".to_string();
    let mut config_errors: Vec<String>=Vec::new();
    let custom_path: Option<String> = if let Some(c)=config_opt {Some(c)} else {
        if let Ok(home)=env::var("HOME") {
            let p1=format!("{}/.config/xplr/init.lua",home.trim_end_matches('/'));
            if Path::new(&p1).exists() {Some(p1)} else {
                let p2="/etc/xplr/init.lua".to_string();
                if Path::new(&p2).exists() {Some(p2)} else {None}
            }
        } else {
            let p2="/etc/xplr/init.lua".to_string();
            if Path::new(&p2).exists() {Some(p2)} else {None}
        }
    };
    if let Some(ref cp)=custom_path {
        let ca=abs_clean(cp);
        if !Path::new(&ca).is_dir() {
            match load_single_config(&ca) {
                Ok((sh,pf))=>{ if let Some(v)=sh {show_hidden=v;} if let Some(p)=pf {prompt_format=p;} },
                Err(e)=>config_errors.push(e),
            }
        }
    }
    for ec in &extra_config {
        let ea=abs_clean(ec);
        if Path::new(&ea).is_dir() {continue;}
        match load_single_config(&ea) {
            Ok((sh,pf))=>{ if let Some(v)=sh {show_hidden=v;} if let Some(p)=pf {prompt_format=p;} },
            Err(e)=>config_errors.push(e),
        }
    }
    let mut state=AppState{
        pwd: initial_pwd.clone(),
        focus_index:0,
        nodes:Vec::new(),
        selection:Vec::new(),
        selection_set: std::collections::HashSet::new(),
        vroot: vroot_abs_opt.clone(),
        initial_vroot: vroot_abs_opt.clone(),
        show_hidden, write0,
        print_pwd_as_result,
        logs:Vec::new(),
        history:Vec::new(),
        history_index:0,
        prompt_format,
    };
    for e in &config_errors { state.logs.push(format!("ERROR) {}",e)); }
    let has_errors=!config_errors.is_empty();
    let mut filters: Vec<(NodeFilter,String)>=Vec::new();
    let mut sorters: Vec<(NodeSorter,bool)>=Vec::new();
    state.nodes=list_filtered(&state,filters.as_slice(),sorters.as_slice());
    if let Some(ref f)=initial_focus {
        if let Some(idx)=state.nodes.iter().position(|n| &n.path==f) {state.focus_index=idx;}
        else {state.focus_index=0;}
    } else {state.focus_index=0;}
    for sel in &init_sel_abs {
        if !state.selection_set.contains(sel) {state.selection_set.insert(sel.clone()); state.selection.push(sel.clone());}
    }
    state.history.push(state.pwd.clone());
    state.history_index=0;
    for msg_str in &on_load {
        let rm=parse_runtime(msg_str);
        if let Some(code)=exec_msg(&mut state,&rm,&mut filters,&mut sorters) {
            return code;
        }
    }
    return run_interactive(state, filters, sorters, has_errors);
}

